CREATE TABLE IF NOT EXISTS system_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS identity_nodes(node_id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS identity_members(member_id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS identity_credentials(credential_id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES identity_members(member_id),credential_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS identity_access_events(id INTEGER PRIMARY KEY AUTOINCREMENT,credential_id TEXT NOT NULL,member_id TEXT,result TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS financial_accounts(account_id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES identity_members(member_id),account_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS financial_ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,account_id TEXT NOT NULL REFERENCES financial_accounts(account_id),direction TEXT NOT NULL CHECK(direction IN ('debit','credit')),amount INTEGER NOT NULL CHECK(amount>0),reference TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_transactions(transaction_id TEXT PRIMARY KEY,credential_id TEXT NOT NULL,account_id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS loan_accounts(loan_id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES identity_members(member_id),principal INTEGER NOT NULL,installment_amount INTEGER NOT NULL,remaining_balance INTEGER NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vending_machines(machine_id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'offline',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vending_products(product_id TEXT PRIMARY KEY,name TEXT NOT NULL,price INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS vending_inventory(machine_id TEXT NOT NULL REFERENCES vending_machines(machine_id),product_id TEXT NOT NULL REFERENCES vending_products(product_id),slot TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(machine_id,slot));
CREATE TABLE IF NOT EXISTS vending_stock_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,machine_id TEXT NOT NULL,product_id TEXT NOT NULL,quantity INTEGER NOT NULL,movement_type TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vending_transactions(transaction_id TEXT PRIMARY KEY,machine_id TEXT NOT NULL,product_id TEXT NOT NULL,amount INTEGER NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS device_registry(device_id TEXT PRIMARY KEY,device_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',last_seen TEXT);
CREATE TABLE IF NOT EXISTS device_events(id INTEGER PRIMARY KEY AUTOINCREMENT,device_id TEXT NOT NULL,event_type TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,event_type TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,detail TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO system_meta(key,value) VALUES('schema_version','001');
